// Actual guest handler with simulated datastore; no live calls or real recovery codes.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {stripTypeScriptTypes} from 'node:module';
import {checkCharacterSave,fingerprintCharacterSave} from '../../../base44/shared/characterSaveRules.ts';
const source=fs.readFileSync(new URL('../../../base44/functions/guestCharacterVault/entry.ts',import.meta.url),'utf8').replace(/^import .*;\n/gm,'');
function fixture(){
 const rows=[],quotas=[{id:'q1',action:'register',window_start:0,used:0},{id:'q2',action:'recover',window_start:0,used:0}];let handler,hold=null;
 const matches=(r,q)=>Object.entries(q).every(([k,v])=>typeof v==='object'&&v!==null&&'$lt'in v?r[k]<v.$lt:r[k]===v);
 const collection={filter:async(q,sort,limit)=>structuredClone(rows.filter(r=>matches(r,q)).slice(0,limit)),create:async r=>{rows.push({...structuredClone(r),id:'row'+rows.length});},update:async(id,patch)=>{if(hold)await hold();Object.assign(rows.find(r=>r.id===id),structuredClone(patch));}};
 const quota={filter:async q=>structuredClone(quotas.filter(r=>matches(r,q))),updateMany:async(q,patch)=>{const r=quotas.find(x=>matches(x,q));if(!r)return{updated:0};Object.assign(r,patch.$set||{});if(patch.$inc)r.used+=patch.$inc.used;return{updated:1};}};
 new Function('Deno','createClientFromRequest','checkCharacterSave','fingerprintCharacterSave',stripTypeScriptTypes(source))({serve:f=>handler=f},()=>({asServiceRole:{entities:{GuestVaultQuota:quota,Game3DGuestCharacterSave:collection}}}),checkCharacterSave,fingerprintCharacterSave);
 const call=async(action,data)=>{const r=await handler(new Request('https://fixture.invalid',{method:'POST',body:JSON.stringify({action,data})}));return{status:r.status,body:await r.json()}};
 const register=async(id='char_one',name='Fixture Hero')=>{const r=await call('register',{characterId:id,rosterEntry:{name}});assert.equal(r.status,200);return{characterId:id,recoveryCode:r.body.recoveryCode};};
 return{rows,quotas,call,register,setHold:f=>hold=f};
}
test('registration stores hash only; same names recover separately',async()=>{const f=fixture(),a=await f.register(),b=await f.register('char_two');assert.match(a.recoveryCode,/^[A-F0-9]{40}$/);assert.notEqual(a.recoveryCode,b.recoveryCode);assert.match(f.rows[0].recovery_hash,/^[a-f0-9]{64}$/);assert.equal(JSON.stringify(f.rows).includes(a.recoveryCode),false);const r=await f.call('recover',{name:'Fixture Hero',recoveryCode:b.recoveryCode});assert.equal(r.body.characterId,'char_two');assert.equal(r.body.save,null);});
test('wrong code cannot read or delete another character',async()=>{const f=fixture(),a=await f.register(),b=await f.register('char_two');for(const action of ['get','delete'])assert.equal((await f.call(action,{characterId:a.characterId,recoveryCode:b.recoveryCode})).status,404);assert.equal(f.rows[0].deleted_at,undefined);});
test('save revision, prior snapshot, stale conflict and explicit overwrite',async()=>{const f=fixture(),a=await f.register();const put=(rev,value,overwrite=false)=>f.call('put',{...a,expectedRevision:rev,data:{fixture_state:JSON.stringify(value)},overwrite});assert.equal((await put(0,1)).body.save.revision,1);assert.equal((await put(0,2)).status,409);assert.equal((await put(1,2)).body.save.revision,2);assert.equal(f.rows[0].previous_data.fixture_state,'1');assert.equal((await put(0,3,true)).body.save.revision,3);assert.equal(f.rows[0].previous_data.fixture_state,'2');});
test('invalid stored value rejected without mutation; tombstone refuses recovery',async()=>{const f=fixture(),a=await f.register();assert.equal((await f.call('put',{...a,expectedRevision:0,data:{fixture_state:42}})).status,422);assert.equal(f.rows[0].revision,0);assert.equal((await f.call('delete',a)).status,200);assert.equal((await f.call('get',a)).status,404);assert.equal((await f.call('recover',{name:'Fixture Hero',recoveryCode:a.recoveryCode})).status,404);});
test('missing or duplicate quota rows fail closed',async()=>{for(const duplicate of [false,true]){const f=fixture();f.quotas.splice(0,1,...(duplicate?[{id:'a',action:'register'},{id:'b',action:'register'}]:[]));const r=await f.call('register',{characterId:'char_one',rosterEntry:{name:'Fixture Hero'}});assert.equal(r.status,500);assert.equal(f.rows.length,0);}});
test('diagnostic: competing same-revision puts both succeed with unconditional update',async()=>{const f=fixture(),a=await f.register();let arrive=0,release;const gate=new Promise(r=>release=r);f.setHold(async()=>{if(++arrive===2)release();await gate;});const put=v=>f.call('put',{...a,expectedRevision:0,data:{fixture_state:JSON.stringify(v)}});const results=await Promise.all([put(1),put(2)]);assert.deepEqual(results.map(r=>r.status),[200,200]);assert.deepEqual(results.map(r=>r.body.save.revision),[1,1]);assert.equal(f.rows[0].revision,1);});
